mapper.select:
SELECT u.user_id AS userId, u.user_type AS userType, COALESCE(s.name, i.name) AS userName FROM sys_user u LEFT JOIN student s ON u.ref_id = s.id AND u.user_type = 'STUDENT' LEFT JOIN instructor i ON u.ref_id = i.id AND u.user_type = 'INSTRUCTOR' WHERE u.user_type IN ('STUDENT', 'INSTRUCTOR') AND u.enabled = 1
AND COALESCE(s.dept_name, i.dept_name) = #{dept}
AND u.user_type = #{role}
AND ( u.user_id = #{keyword} OR u.user_id LIKE CONCAT(#{keyword}, '%')
OR MATCH(s.name) AGAINST (#{keyword} IN BOOLEAN MODE) OR MATCH(i.name) AGAINST (#{keyword} IN BOOLEAN MODE)
OR s.name LIKE CONCAT('%', #{keyword}, '%') OR i.name LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY u.user_type, u.user_id LIMIT #{limit}
